// Confere o formulário e cria o calendário vazio (código + chave secreta).
let b = $('🔔 Pedido do calendário (POST)').first().json.body;
if (typeof b === 'string') { try { b = JSON.parse(b); } catch (e) { b = {}; } }
b = b || {};
const crypto = require('crypto');
const limpa = (v, max) => String(v ?? '').replace(/[\u0000-\u0008\u000b-\u001f\u007f<>]/g, ' ').replace(/[ \t]+/g, ' ').trim().slice(0, max);
const slug = s => String(s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '').slice(0, 30);
const ESTILOS = ['escuro', 'claro', 'vibrante', 'natural', 'corporativo'];
const hoje = new Date(Date.now() - 3 * 3600000);
const amanha = new Date(hoje.getTime() + 86400000).toISOString().slice(0, 10);
const negocio = {
  nome: limpa(b.nome, 60), nicho: limpa(b.nicho, 80), vende: limpa(b.vende, 1500), publico: limpa(b.publico, 300),
  objetivo: limpa(b.objetivo, 60), tom: limpa(b.tom, 40), ofertas: limpa(b.ofertas, 400),
  perfil: limpa(b.perfil, 40).replace(/^@/, '').replace(/[^a-zA-Z0-9._]/g, ''),
  cor: /^#[0-9a-fA-F]{6}$/.test(b.cor || '') ? b.cor : '', estilo: ESTILOS.includes(b.estilo) ? b.estilo : 'escuro',
};
const inicio = /^\d{4}-\d{2}-\d{2}$/.test(b.inicio || '') && b.inicio >= hoje.toISOString().slice(0, 10) ? b.inicio : amanha;
const hora = /^\d{2}:\d{2}$/.test(b.hora || '') ? b.hora : '11:00';
const erros = [];
if (negocio.nome.length < 2) erros.push('Digite o nome do negócio.');
if (negocio.nicho.length < 3) erros.push('Diga a área do negócio.');
if (negocio.vende.length < 5) erros.push('Conte o que o negócio vende.');
const id = (slug(negocio.nome) || 'calendario') + '-' + crypto.randomBytes(2).toString('hex');
const chave = crypto.randomBytes(6).toString('hex');
const base = String($('🔔 Pedido do calendário (POST)').first().json.webhookUrl || '').split('/webhook/')[0] + '/webhook';
const cal = { id, chave, criado_em: new Date().toISOString(), status: 'planejando', escritos: 0, negocio, inicio, hora, auto: false, pilares: [], dias: [] };
return [{ json: { valido: erros.length === 0, erros, id, chave, cal: JSON.stringify(cal), negocio, inicio,
  link: `${base}/posts30-ver?id=${id}&chave=${chave}`, chave_limite: '<SEGREDO_REMOVIDO>' + new Date().toISOString().slice(0, 13) } }];

function parseJSON(txt) {
  const s = String(txt || '').replace(/^\s*```(?:json)?\s*/i, '').replace(/```\s*$/i, '').trim();
  try { return JSON.parse(s); } catch (e) {}
  const a = s.indexOf('{'), b = s.lastIndexOf('}');
  if (a > -1 && b > a) { try { return JSON.parse(s.slice(a, b + 1)); } catch (e) {} }
  return null;
}

// Transforma o plano da IA em 30 dias com data. Se a IA falhar, monta um plano padrão (para não travar).
const v = $('🧩 Confere o pedido').first().json;
const cal = JSON.parse(v.cal);
let ia = null;
try { ia = parseJSON($('🤖 Estrategista').first().json.output); } catch (e) {}
const FORMATOS = ['post', 'carrossel', 'reels'];
const txt = (s, max) => String(s ?? '').replace(/[<>]/g, '').trim().slice(0, max);
let dias = Array.isArray(ia && ia.dias) ? ia.dias : [];
const padrao = ['carrossel', 'post', 'reels', 'carrossel', 'post', 'carrossel', 'reels'];
const pilares = (Array.isArray(ia && ia.pilares) ? ia.pilares : []).map(p => txt(p, 30)).filter(Boolean).slice(0, 5);
if (!pilares.length) pilares.push('Dicas', 'Bastidores', 'Produtos', 'Clientes', 'Ofertas');
const dataDe = n => { const d = new Date(cal.inicio + 'T12:00:00Z'); d.setUTCDate(d.getUTCDate() + n); return d.toISOString().slice(0, 10); };
cal.dias = Array.from({ length: 30 }, (_, i) => {
  const d = dias.find(x => Number(x.dia) === i + 1) || dias[i] || {};
  return {
    dia: i + 1, data: dataDe(i), formato: FORMATOS.includes(d.formato) ? d.formato : padrao[i % 7],
    pilar: txt(d.pilar, 30) || pilares[i % pilares.length], tema: txt(d.tema, 140) || `${pilares[i % pilares.length]} da ${cal.negocio.nome}`,
    objetivo: txt(d.objetivo, 20) || 'engajar', titulo: '', subtitulo: '', slides: [], roteiro: [], legenda: '', hashtags: [],
    estado: 'planejado', v: 1, link: '', erro: '',
  };
});
cal.pilares = pilares;
cal.plano_ia = !!(ia && Array.isArray(ia.dias) && ia.dias.length >= 20);
cal.status = 'escrevendo';
// 5 lotes de 6 dias: a IA redatora escreve um lote por vez e o calendário vai enchendo na tela
const lotes = [0, 1, 2, 3, 4].map(l => ({ json: { lote: l + 1, dias: cal.dias.slice(l * 6, l * 6 + 6).map(d => ({ dia: d.dia, data: d.data, formato: d.formato, pilar: d.pilar, tema: d.tema, objetivo: d.objetivo })) } }));
return [{ json: { id: cal.id, cal: JSON.stringify(cal), lotes } }];

function parseJSON(txt) {
  const s = String(txt || '').replace(/^\s*```(?:json)?\s*/i, '').replace(/```\s*$/i, '').trim();
  try { return JSON.parse(s); } catch (e) {}
  const a = s.indexOf('{'), b = s.lastIndexOf('}');
  if (a > -1 && b > a) { try { return JSON.parse(s.slice(a, b + 1)); } catch (e) {} }
  return null;
}

// Pega o texto que a IA escreveu para o lote e grava dentro do calendário (lido de novo do Redis, para não perder edições).
const cal = JSON.parse($('📖 Lê o calendário (lote)').first().json.cal || 'null');
const lote = $('🔁 Um lote por vez').first().json;
let ia = null;
try { ia = parseJSON($('🤖 Redatora').first().json.output); } catch (e) {}
const posts = Array.isArray(ia && ia.posts) ? ia.posts : [];
const txt = (s, max) => String(s ?? '').replace(/[<>]/g, '').trim().slice(0, max);
const tag = t => '#' + String(t).replace(/^#/, '').replace(/[^\p{L}\p{N}_]/gu, '');
for (const alvo of lote.dias) {
  const d = cal.dias[alvo.dia - 1];
  const p = posts.find(x => Number(x.dia) === alvo.dia);
  if (!p) { d.estado = 'erro'; d.erro = 'A IA não escreveu este dia. Use "Refazer com IA".'; continue; }
  Object.assign(d, {
    titulo: txt(p.titulo, 70), subtitulo: txt(p.subtitulo, 120),
    slides: d.formato === 'carrossel' ? (Array.isArray(p.slides) ? p.slides : []).slice(0, 4).map(s => ({ titulo: txt(s.titulo, 60), texto: txt(s.texto, 240) })) : [],
    roteiro: d.formato === 'reels' ? (Array.isArray(p.roteiro) ? p.roteiro : []).slice(0, 8).map(r => ({ tempo: txt(r.tempo, 12), cena: txt(r.cena, 160), fala: txt(r.fala, 220) })) : [],
    legenda: txt(p.legenda, 1800), hashtags: (Array.isArray(p.hashtags) ? p.hashtags : []).map(tag).filter(t => t.length > 2).slice(0, 10),
    estado: 'rascunho', erro: '',
  });
  while (d.formato === 'carrossel' && d.slides.length < 4) d.slides.push({ titulo: d.titulo, texto: d.subtitulo || 'Salve para ver depois.' });
}
cal.escritos = cal.dias.filter(d => d.estado !== 'planejado').length;
if (lote.lote === 5) cal.status = 'pronto';
return [{ json: { cal: JSON.stringify(cal) } }];

// Calcula a arte de UMA imagem (dia + número do slide): cores, tamanho das letras e posição centralizada.
const q = $('🔔 Pedido de imagem (GET)').first().json.query || {};
let cal = null;
try { cal = JSON.parse($('📖 Lê o calendário (imagem)').first().json.cal || 'null'); } catch (e) {}
const dia = cal && cal.dias[Number(q.dia) - 1];
if (!dia || !dia.titulo) return [{ json: { ok: false } }];
const s = Math.max(0, Math.min(4, Number(q.s) || 0));
const n = cal.negocio;
const FONTES = '/usr/share/fonts/truetype/msttcorefonts/';
const PALETAS = {
  escuro: { fundo: '#0f172a', destaque: '#f59e0b', titulo: '#ffffff', texto: '#cbd5e1', rodape: '#94a3b8', tit: 'Verdana_Bold.ttf', txt: 'Verdana.ttf' },
  claro: { fundo: '#fafaf9', destaque: '#e11d48', titulo: '#111827', texto: '#374151', rodape: '#6b7280', tit: 'Verdana_Bold.ttf', txt: 'Verdana.ttf' },
  vibrante: { fundo: '#5b21b6', destaque: '#facc15', titulo: '#ffffff', texto: '#ede9fe', rodape: '#ddd6fe', tit: 'Verdana_Bold.ttf', txt: 'Verdana.ttf' },
  natural: { fundo: '#f1f5ec', destaque: '#2f855a', titulo: '#1c3324', texto: '#3f5a47', rodape: '#6b8573', tit: 'Georgia_Bold.ttf', txt: 'Georgia.ttf' },
  corporativo: { fundo: '#0b3a6e', destaque: '#38bdf8', titulo: '#ffffff', texto: '#dbeafe', rodape: '#93c5fd', tit: 'Verdana_Bold.ttf', txt: 'Verdana.ttf' },
};
const P = { ...(PALETAS[n.estilo] || PALETAS.escuro) };
if (n.cor) P.destaque = n.cor;

// Sem emoji (as fontes do servidor não têm) e sem aspas retas (quebram o comando de desenho)
const limpa = (t, max) => String(t ?? '').replace(/[\u{1F000}-\u{1FAFF}\u{2600}-\u{27BF}\u{FE0F}\u{200D}\u{2190}-\u{21FF}]/gu, '')
  .replace(/"/g, '”').replace(/'/g, '’').replace(/\\/g, '/').replace(/\s+/g, ' ').trim().slice(0, max);
function quebra(texto, porLinha) {
  const linhas = []; let atual = '';
  for (const p of texto.split(' ')) {
    if ((atual + ' ' + p).trim().length > porLinha && atual) { linhas.push(atual); atual = p; } else atual = (atual + ' ' + p).trim();
  }
  if (atual) linhas.push(atual);
  return linhas;
}
// O que vai em cada imagem
let tipo = 'capa', titulo = dia.titulo, texto = dia.subtitulo;
if (dia.formato === 'carrossel' && s > 0) {
  const sl = dia.slides[s - 1] || {};
  tipo = s === 4 ? 'cta' : 'conteudo'; titulo = sl.titulo || dia.titulo; texto = sl.texto || '';
}
titulo = limpa(titulo, 80); texto = limpa(texto, tipo === 'conteudo' ? 260 : 150);
// Letra diminui quando o título é comprido
const base = tipo === 'capa' ? 88 : tipo === 'cta' ? 72 : 64;
const tTam = Math.max(48, Math.min(base, Math.floor(base * Math.sqrt(36 / Math.max(36, titulo.length)) * 1.12)));
const porLinhaT = Math.floor(900 / (tTam * 0.66));
const tLinhas = quebra(titulo, porLinhaT).slice(0, 6);
const xTam = tipo === 'conteudo' ? 42 : 44;
const xLinhas = texto ? quebra(texto, Math.floor(900 / (xTam * 0.58))).slice(0, 9) : [];
const tLH = Math.round(tTam * 1.2), xLH = Math.round(xTam * 1.3);
const altura = tLinhas.length * tLH + (xLinhas.length ? 56 + xLinhas.length * xLH : 0);
const topo = 220 + Math.max(0, Math.round((930 - altura) / 2));
const etiqueta = dia.formato === 'reels' ? 'REELS' : dia.formato === 'carrossel' ? `${s + 1}/5` : limpa(dia.pilar, 24).toUpperCase();
const seta = dia.formato === 'carrossel' ? (s < 4 ? 'arraste  »' : 'salve e compartilhe') : (dia.formato === 'reels' ? 'assista até o fim' : 'salve este post');
return [{ json: {
  ok: true, chave: `p30img:${cal.id}:${dia.dia}:${s}:${dia.v}`, cor: P,
  titulo: tLinhas.join('\n'), texto: xLinhas.join('\n') || ' ', tTam, xTam,
  tY: Math.round(topo + tTam * 0.85), xY: Math.round(topo + tLinhas.length * tLH + 56 + xTam * 0.85),
  etiqueta, rodape: n.perfil ? '@' + n.perfil : limpa(n.nome, 40), seta, setaX: Math.max(90, 990 - Math.round(seta.length * 19)),
  fonteTitulo: FONTES + P.tit, fonteTexto: FONTES + P.txt,
} }];

// Entrega o calendário em JSON para a página (sem a chave secreta).
const q = $('🔔 Dados do calendário (GET)').first().json.query || {};
let cal = null;
try { cal = JSON.parse($('📖 Lê o calendário (dados)').first().json.cal || 'null'); } catch (e) {}
if (!cal || String(q.chave || '') !== cal.chave) return [{ json: { codigo: 403, corpo: JSON.stringify({ ok: false, erro: 'Link inválido.' }) } }];
const { chave, ...publico } = cal;
return [{ json: { codigo: 200, corpo: JSON.stringify({ ok: true, cal: publico }) } }];

// Ações do calendário: aprovar, voltar para rascunho, salvar texto editado, configurar a publicação automática.
// "refazer" só é preparado aqui; quem reescreve é a IA, no próximo passo.
let b = $('🔔 Ação no calendário (POST)').first().json.body;
if (typeof b === 'string') { try { b = JSON.parse(b); } catch (e) { b = {}; } }
b = b || {};
let cal = null;
try { cal = JSON.parse($('📖 Lê o calendário (ação)').first().json.cal || 'null'); } catch (e) {}
const falha = erro => [{ json: { acao: 'erro', resposta: JSON.stringify({ ok: false, erro }) } }];
if (!cal || String(b.chave || '') !== cal.chave) return falha('Chave do calendário errada.');
const txt = (s, max) => String(s ?? '').replace(/[<>]/g, '').trim().slice(0, max);
const d = cal.dias[Number(b.dia) - 1];
const precisaDia = ['aprovar', 'rascunho', 'salvar', 'refazer'];
if (precisaDia.includes(b.acao) && !d) return falha('Dia inválido.');
if (precisaDia.includes(b.acao) && d.estado === 'publicado') return falha('Este post já foi publicado.');

switch (b.acao) {
  case 'aprovar': if (d.titulo) d.estado = 'aprovado'; break;
  case 'rascunho': d.estado = 'rascunho'; break;
  case 'aprovar_todos': cal.dias.forEach(x => { if (x.estado === 'rascunho' && x.formato !== 'reels') x.estado = 'aprovado'; }); break;
  case 'salvar':
    d.titulo = txt(b.titulo, 70) || d.titulo; d.subtitulo = txt(b.subtitulo, 120);
    d.legenda = txt(b.legenda, 2000);
    d.hashtags = String(b.hashtags || '').split(/[\s,]+/).map(t => t.replace(/^#*/, '#').replace(/[^#\p{L}\p{N}_]/gu, '')).filter(t => t.length > 2).slice(0, 15);
    d.v++; if (d.estado === 'aprovado') d.estado = 'rascunho';
    break;
  case 'config':
    cal.auto = b.auto === true;
    if (/^\d{2}:\d{2}$/.test(b.hora || '')) cal.hora = b.hora;
    break;
  case 'refazer':
    return [{ json: { acao: 'refazer', id: cal.id, cal: JSON.stringify(cal), dia: d.dia, pedido: txt(b.pedido, 300), post: d, negocio: cal.negocio } }];
  default: return falha('Ação desconhecida.');
}
return [{ json: { acao: 'salvar', id: cal.id, cal: JSON.stringify(cal), resposta: JSON.stringify({ ok: true }) } }];

function parseJSON(txt) {
  const s = String(txt || '').replace(/^\s*```(?:json)?\s*/i, '').replace(/```\s*$/i, '').trim();
  try { return JSON.parse(s); } catch (e) {}
  const a = s.indexOf('{'), b = s.lastIndexOf('}');
  if (a > -1 && b > a) { try { return JSON.parse(s.slice(a, b + 1)); } catch (e) {} }
  return null;
}

// Troca o post do dia pelo novo texto da IA (a versão "v" sobe para as imagens serem redesenhadas).
const a = $('🧩 Confere a ação').first().json;
const cal = JSON.parse(a.cal);
const d = cal.dias[a.dia - 1];
let ia = null;
try { ia = parseJSON($('🤖 Redatora (refazer)').first().json.output); } catch (e) {}
const p = ia && (Array.isArray(ia.posts) ? ia.posts[0] : ia);
if (!p || !p.titulo) return [{ json: { id: cal.id, cal: a.cal, resposta: JSON.stringify({ ok: false, erro: 'A IA não respondeu agora. Tente de novo.' }) } }];
const txt = (s, max) => String(s ?? '').replace(/[<>]/g, '').trim().slice(0, max);
Object.assign(d, {
  titulo: txt(p.titulo, 70), subtitulo: txt(p.subtitulo, 120), legenda: txt(p.legenda, 1800),
  hashtags: (Array.isArray(p.hashtags) ? p.hashtags : []).map(t => '#' + String(t).replace(/^#/, '').replace(/[^\p{L}\p{N}_]/gu, '')).filter(t => t.length > 2).slice(0, 10),
  slides: d.formato === 'carrossel' ? (Array.isArray(p.slides) ? p.slides : []).slice(0, 4).map(s => ({ titulo: txt(s.titulo, 60), texto: txt(s.texto, 240) })) : [],
  roteiro: d.formato === 'reels' ? (Array.isArray(p.roteiro) ? p.roteiro : []).slice(0, 8).map(r => ({ tempo: txt(r.tempo, 12), cena: txt(r.cena, 160), fala: txt(r.fala, 220) })) : [],
  estado: 'rascunho', erro: '', v: d.v + 1,
});
while (d.formato === 'carrossel' && d.slides.length < 4) d.slides.push({ titulo: d.titulo, texto: d.subtitulo || 'Salve para ver depois.' });
cal.escritos = cal.dias.filter(x => x.estado !== 'planejado').length;
return [{ json: { id: cal.id, cal: JSON.stringify(cal), resposta: JSON.stringify({ ok: true }) } }];

// A cada 15 minutos: procura UM post aprovado cuja hora já chegou, num calendário com publicação automática ligada.
const W = 'https://webhookn8n6.inovareinteligenciaartificial.com/webhook';
const agora = Date.now();
const todos = Object.entries($input.first().json || {}).filter(([k]) => /^p30cal:[a-z0-9-]+$/.test(k));
for (const [, v] of todos) {
  let cal; try { cal = JSON.parse(v); } catch (e) { continue; }
  if (!cal.auto) continue;
  for (const d of cal.dias) {
    if (d.estado !== 'aprovado' || d.formato === 'reels') continue;
    const quando = Date.parse(`${d.data}T${cal.hora}:00-03:00`); // horário de Brasília
    if (quando > agora || agora - quando > 3 * 86400000) continue; // ainda não chegou / atrasado demais (3 dias)
    const img = s => `${W}/posts30-img?id=${cal.id}&dia=${d.dia}&s=${s}&v=${d.v}`;
    const legenda = (d.legenda + (d.hashtags.length ? '\n\n' + d.hashtags.join(' ') : '')).slice(0, 2200);
    return [{ json: { id: cal.id, dia: d.dia, formato: d.formato, legenda, urls: d.formato === 'carrossel' ? [0, 1, 2, 3, 4].map(img) : [img(0)] } }];
  }
}
return [];

const r = $input.first().json || {};
const erro = r.error ? String(r.error.message || r.error.description || JSON.stringify(r.error)).slice(0, 200) : '';
return [{ json: { link: r.permalink || '', erro: erro || (r.permalink || r.id ? '' : 'o Instagram não confirmou a publicação') } }];

// Anota no calendário se o post foi publicado (com o link) ou se deu erro (para o dono ver e tentar de novo).
const alvo = $('🧩 Quem publica agora?').first().json;
const r = $('🧩 Resultado do Instagram').first().json;
const cal = JSON.parse($('📖 Lê o calendário (publicação)').first().json.cal || 'null');
if (!cal) return [];
const d = cal.dias[alvo.dia - 1];
if (r.erro) { d.estado = 'erro'; d.erro = 'Instagram recusou: ' + r.erro; }
else { d.estado = 'publicado'; d.link = r.link || ''; d.publicado_em = new Date().toISOString(); d.erro = ''; }
return [{ json: { id: cal.id, cal: JSON.stringify(cal) } }];

// O fluxo responde na hora com o link; a IA continua escrevendo em segundo plano.
const r = $input.first().json;
if (!r.ok) throw new Error('O fluxo recusou o teste: ' + (r.erros || [r.message || 'sem resposta']).join(' '));
const q = String(r.link).split('?')[1] || '';
const p = Object.fromEntries(q.split('&').map(x => x.split('=')));
return [{ json: { '👉 abra para ver enchendo': r.link, link: r.link, id: p.id, chave: p.chave } }];

// pronto = resumo do mês · demorou demais = o node fica vermelho com o motivo
const cal = $input.first().json.cal || {}, l = $('👉 Abra o calendário (link)').first().json;
if (cal.status !== 'pronto') throw new Error('Passou de 10 minutos e o mês não terminou (' + (cal.escritos || 0) + ' de 30 prontos). Veja na aba Executions.');
return [{ json: { '✅': cal.escritos + ' de 30 posts prontos', '📅 abra o calendário': l.link, '🧱 pilares': cal.pilares,
  '🗓️ primeiros dias': (cal.dias || []).slice(0, 3).map(d => d.data + ' · ' + d.formato + ' · ' + (d.titulo || d.tema)),
  '🛡️': 'Nada foi publicado: a publicação automática começa desligada.' } }];

// Confere o formulário e cria o calendário vazio (código + chave secreta).
let b = $('🔔 Pedido do calendário (POST)').first().json.body;
if (typeof b === 'string') { try { b = JSON.parse(b); } catch (e) { b = {}; } }
b = b || {};
const crypto = require('crypto');
const limpa = (v, max) => String(v ?? '').replace(/[\u0000-\u0008\u000b-\u001f\u007f<>]/g, ' ').replace(/[ \t]+/g, ' ').trim().slice(0, max);
const slug = s => String(s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '').slice(0, 30);
const ESTILOS = ['escuro', 'claro', 'vibrante', 'natural', 'corporativo'];
const hoje = new Date(Date.now() - 3 * 3600000);
const amanha = new Date(hoje.getTime() + 86400000).toISOString().slice(0, 10);
const negocio = {
  nome: limpa(b.nome, 60), nicho: limpa(b.nicho, 80), vende: limpa(b.vende, 1500), publico: limpa(b.publico, 300),
  objetivo: limpa(b.objetivo, 60), tom: limpa(b.tom, 40), ofertas: limpa(b.ofertas, 400),
  perfil: limpa(b.perfil, 40).replace(/^@/, '').replace(/[^a-zA-Z0-9._]/g, ''),
